import { allowExpectedDiagnostic, expect, test } from "./journey.js";
import { readFileSync } from "node:fs";

// Generated by the canonical SIR.Simulation.Replay encoder from the retained
// PerspectivePlayback package used by SIR.Client.Tests; the engine hash is
// intentionally embedded so a changed engine rejects this fixture.
const retainedReplay = Buffer.from(
  readFileSync(new URL("../fixtures/retained-perspective-replay.sirr.base64", import.meta.url), "utf8").trim(),
  "base64",
);

// Diagnostics-gate self-tests deliberately issue a browser fetch; they are not product-journey evidence.
test("explicitly allowed rejection diagnostics do not hide unrelated browser failures", async ({ page }) => {
  await page.route("**/controlled-rejection", (route) => route.fulfill({ status: 418, body: "expected" }));
  allowExpectedDiagnostic(page, /controlled-rejection|I'm a teapot/);
  await page.goto("/");
  await page.evaluate(() => fetch("/controlled-rejection"));
});

test("unexpected rejection diagnostics fail the journey gate", async ({ page }) => {
  test.skip(process.env.SIR_DIAGNOSTIC_SELF_TEST !== "1", "diagnostic gate child-process self-test only");
  await page.route("**/unexpected-rejection", (route) => route.fulfill({ status: 418, body: "unexpected" }));
  // Isolate the network threshold: Chromium emits a generic 418 console message
  // for fetch, while this child specifically proves the unallowlisted response gate.
  allowExpectedDiagnostic(page, /I'm a teapot/);
  await page.goto("/");
  await page.evaluate(() => fetch("/unexpected-rejection"));
});

test("visible mode controls preserve a usable tactical workspace across authoring modes", async ({ page }) => {
  await page.goto("/");
  const workspace = page.getByRole("main", { name: "S.I.R. simulator and editor" });
  await expect(workspace).toBeVisible();

  for (const mode of ["Editor", "Plan", "Simulate", "Review"]) {
    const control = page.getByRole("button", { name: mode, exact: true });
    await control.click();
    await expect(control).toHaveAttribute("aria-pressed", "true");
    await expect(workspace.getByRole("application")).toBeVisible();
  }
});

test("disabled playback names why it is unavailable before a simulation is loaded", async ({ page }) => {
  await page.goto("/");
  const play = page.getByRole("button", { name: "Play tactical timeline", exact: true });
  await expect(play).toBeDisabled();
  await expect(page.getByText(/Play unavailable:/)).toBeVisible();
});

test("the normal UI remains operable at 400 percent browser zoom", async ({ page }) => {
  await page.goto("/");
  // Use Chromium's actual browser zoom shortcut: this is intentionally not a
  // CSS/device-scale emulation or an implementation-state assertion.
  await page.keyboard.press("Control++");
  await page.keyboard.press("Control++");
  await page.keyboard.press("Control++");
  await page.keyboard.press("Control++");
  await expect(page.getByRole("main", { name: "S.I.R. simulator and editor" })).toBeVisible();
  await page.getByRole("button", { name: "Simulate", exact: true }).click();
  await page.getByRole("button", { name: "Show contextual actions", exact: true }).click();
  await expect(page.getByRole("button", { name: "Open simulator samples", exact: true })).toBeVisible();
});

test("a valid map selected through the visible import control reports success", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Editor", exact: true }).click();
  await page.getByRole("button", { name: "Expand Document / revision panel", exact: true }).click();
  const picker = page.getByLabel("Import SIR map", { exact: true });
  await expect(picker).toBeVisible();
  await picker.setInputFiles({
    name: "invalid.sir-map",
    mimeType: "text/plain",
    buffer: Buffer.from("not a SIR map"),
  });
  await expect(page.getByRole("alert")).toContainText(/not a supported|Map line/i);
  await picker.setInputFiles({
    name: "visible-success.sir-map",
    mimeType: "text/plain",
    buffer: Buffer.from("SIR-MAP 2\nsize 4 4\n"),
  });
  await expect(page.getByRole("alert")).toContainText("Imported map visible-success.sir-map.");
});

test("the visible replay picker rejects corruption then loads the engine-bound retained package", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Review", exact: true }).click();
  const picker = page.getByLabel("Choose replay package", { exact: true });
  await expect(picker).toBeVisible();
  const corrupt = Buffer.from(retainedReplay);
  corrupt[corrupt.length - 1] ^= 0x01;
  await picker.setInputFiles({ name: "corrupt.sirr", mimeType: "application/octet-stream", buffer: corrupt });
  await expect(page.getByText(/corrupt\.sirr rejected:/)).toBeVisible();
  await picker.setInputFiles({ name: "retained.sirr", mimeType: "application/octet-stream", buffer: retainedReplay });
  await expect(page.getByText(/Loaded retained\.sirr/)).toBeVisible();
});

test("the visible background picker rejects an oversized file then reports attachment", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Editor", exact: true }).click();
  await page.getByRole("button", { name: "Expand Document / revision panel", exact: true }).click();
  const picker = page.getByLabel("Choose local raster map background", { exact: true });
  await expect(picker).toBeVisible();
  await picker.setInputFiles({ name: "too-large.png", mimeType: "image/png", buffer: Buffer.alloc(10_485_761) });
  await expect(page.getByRole("alert")).toContainText(/allowed maximum/i);
  await picker.setInputFiles({
    name: "attached.png",
    mimeType: "image/png",
    buffer: Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScL9bQAAAABJRU5ErkJggg==", "base64"),
  });
  await expect(page.getByRole("alert")).toContainText("Attached background attached.png.");
});

test("a curated sample creates a visible simulator handoff and playback can reset", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Simulate", exact: true }).click();
  await expect(page.getByRole("button", { name: "Play tactical timeline", exact: true })).toBeDisabled();
  await page.getByRole("button", { name: "Show contextual actions", exact: true }).click();
  await page.getByRole("button", { name: "Open simulator samples", exact: true }).click();
  await page.getByRole("button", { name: /^Load simulation sample:/ }).first().click();

  const play = page.getByRole("button", { name: "Play tactical timeline", exact: true });
  await expect(play).toBeEnabled();
  await play.click();
  const pause = page.getByRole("button", { name: "Pause tactical timeline", exact: true });
  await expect(pause).toBeVisible();
  await pause.click();
  await page.getByRole("button", { name: "Step tactical timeline forward", exact: true }).click();
  page.once("dialog", (dialog) => dialog.accept());
  await page.getByRole("button", { name: "Reset simulation to its immutable revision", exact: true }).filter({ hasText: "Reset simulation" }).click();
  await expect(page.getByText(/Authoritative runtime tick 0/)).toBeVisible();
});

test("live authority reconnect remains visible through the production command surface", async ({ page }) => {
  await page.goto("/");
  const live = page.getByRole("region", { name: "Authoritative live session" });
  await expect(live).toContainText("live connected", { timeout: 90_000 });
  await page.getByRole("button", { name: "Disconnect the player-visible live session" }).click();
  await expect(live).toContainText("live disconnected");
  await page.getByRole("button", { name: "Reconnect and request the authoritative live snapshot" }).click();
  await expect(live).toContainText("live connected");
});
